\documentclass[11pt]{amsart}

\usepackage{amsmath, amssymb, amsthm}
\usepackage[margin=1in]{geometry}
\usepackage{hyperref}

\theoremstyle{plain}
\newtheorem{theorem}{Theorem}[section]
\newtheorem{lemma}[theorem]{Lemma}
\newtheorem{corollary}[theorem]{Corollary}
\theoremstyle{definition}
\newtheorem{definition}[theorem]{Definition}

\newcommand{\Sunder}{\underline{S}}
\newcommand{\Sover}{\overline{S}}
\newcommand{\R}{\mathbb{R}}

\title{The Metric Geometry of Surprise}
\author{Aristotle}
\date{July 10, 2026}

\begin{document}

\begin{abstract}
We develop a quantitative theory of \emph{surprise} built on a deliberately minimal
model: a \emph{setup} is a finite nonempty configuration of real-valued resolutions
arranged along a single interpretive axis. Two canonical readings bracket the
configuration --- the \emph{expected resolution}, the most conservative reading (its
minimum, playing the role of a limit), and the \emph{subverting resolution}, the most
divergent reading (its maximum, playing the role of a colimit). We define the
\emph{surprise} of a setup to be the gap between these poles and prove that this
quantity is a genuine geometric invariant: it is nonnegative, vanishes exactly on
constant configurations, is monotone under enrichment of the setup, and --- most
importantly --- equals the \emph{diameter} of the configuration, i.e.\ the greatest
distance between any two of its resolutions, a description that privileges no
particular pair. We further show that the diameter bound is uniform and attained,
that each extremal resolution is characterized by a universal extremal property, and
that surprise is stable: perturbing every resolution by at most $\varepsilon$ changes
the surprise by at most $2\varepsilon$. These results recast the slogan ``a joke is
the passage from the limit of a setup to its colimit'' as an exact statement in the
metric geometry of finite point sets.
\end{abstract}

\maketitle

\section{Introduction}

Humor is an economy of expectation. A setup marshals a listener's assumptions toward
a natural conclusion; a punchline violates that conclusion in a way that is
nonetheless retroactively coherent. We propose to measure this.

The organizing metaphor is structural. In the abstract study of diagrams, a
\emph{limit} is the canonical conservative resolution of a configuration --- its
universal common lower bound --- while a \emph{colimit} is its canonical divergent
resolution. A joke is a passage from the limit of a setup (where the mind expects the
story to rest) to its colimit (where the punchline lands), and the \emph{funniness}
is the distance travelled. We adopt the simplest faithful model: readings live on a
line. There the limit of a finite configuration is its minimum and the colimit is its
maximum, and the theory becomes an exact statement about the \emph{range} of a finite
set.

\medskip
\noindent\textbf{Contributions.} For a finite nonempty configuration $S \subseteq \R$
we establish: well-definedness and nonnegativity of surprise; a vanishing
characterization identifying the ``pun'' regime; monotonicity under enrichment; the
diameter identity together with a uniform, attained bound; universal properties of
the two extremal resolutions; and a sharp $2$-Lipschitz stability estimate.

\section{The model}

\begin{definition}[Setup]
A \emph{setup} is a finite nonempty subset $S \subseteq \R$. Each element $x \in S$
is a \emph{resolution}: a candidate reading positioned on a single interpretive axis,
smaller values being more conservative and larger values more divergent.
\end{definition}

Because $S$ is finite and nonempty it possesses both a least and a greatest element.

\begin{definition}[Canonical resolutions]
For a setup $S$ write $\Sunder = \min S$ (the \emph{expected resolution}) and
$\Sover = \max S$ (the \emph{subverting resolution}).
\end{definition}

\begin{definition}[Surprise]
The \emph{surprise} (or \emph{humor}) of a setup $S$ is
\[
  H(S) = \Sover - \Sunder = \max S - \min S,
\]
the range of $S$, recast as a numerical invariant of surprise.
\end{definition}

Throughout we use the elementary facts that $\min S \le x \le \max S$ for every
$x \in S$, and in particular $\min S \le \max S$.

\section{Basic properties of surprise}

\begin{theorem}[Nonnegativity]
$H(S) \ge 0$.
\end{theorem}
\begin{proof}
Since $\min S \le \max S$, we have $H(S) = \max S - \min S \ge 0$.
\end{proof}

\begin{theorem}[Pun characterization]
$H(S) = 0$ if and only if $x = y$ for all $x, y \in S$.
\end{theorem}
\begin{proof}
If $H(S) = 0$ then $\max S = \min S$; for any $x,y \in S$ the sandwich
$\min S \le x,y \le \max S$ forces $x = \min S = y$. Conversely, if all readings
coincide then $\max S = \min S$ (both lie in $S$), so $H(S) = 0$.
\end{proof}

\begin{corollary}[Singletons are puns]
For any $a \in \R$, $H(\{a\}) = 0$.
\end{corollary}
\begin{proof}
A single-element set has $\min = \max = a$, so $H(\{a\}) = 0$.
\end{proof}

\begin{theorem}[Monotonicity under enrichment]
If $S \subseteq T$ are finite and nonempty, then $H(S) \le H(T)$.
\end{theorem}
\begin{proof}
Since $\max S \in T$ we have $\max S \le \max T$, and since $\min S \in T$ we have
$\min T \le \min S$. Adding, $H(T) = \max T - \min T \ge \max S - \min S = H(S)$.
\end{proof}

\section{Surprise is a diameter}

\begin{lemma}[Uniform distance bound]\label{lem:bound}
For all $x, y \in S$, $|x - y| \le H(S)$.
\end{lemma}
\begin{proof}
From $x \le \max S$ and $-y \le -\min S$ we get $x - y \le H(S)$; symmetrically
$y - x \le H(S)$. Hence $|x-y| = \max(x-y,\,y-x) \le H(S)$.
\end{proof}

\begin{lemma}[Attainment]\label{lem:attain}
There exist $x, y \in S$ with $|x - y| = H(S)$.
\end{lemma}
\begin{proof}
Take $x = \max S$ and $y = \min S$. Then $x - y = H(S) \ge 0$, so $|x-y| = H(S)$.
\end{proof}

\begin{theorem}[Surprise is the diameter]
$H(S)$ is the greatest element of $\{\, |x-y| : x,y \in S \,\}$; equivalently, $H(S)$
is the diameter of the configuration $S$.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:bound}, $H(S)$ is an upper bound for the set of pairwise distances;
by Lemma~\ref{lem:attain}, $H(S)$ is a member of that set. A value that is both an
upper bound and a member of a set is its greatest element.
\end{proof}

This certifies that surprise is \emph{coordinate-free}: it privileges no particular
pair of readings but equals the supremum of all pairwise distances.

\section{Universal properties of the poles}

\begin{theorem}[Colimit property of the subverting resolution]
$\max S$ is the greatest element of $S$: it lies in $S$, and $x \le \max S$ for all
$x \in S$.
\end{theorem}

\begin{theorem}[Limit property of the expected resolution]
$\min S$ is the least element of $S$: it lies in $S$, and $\min S \le x$ for all
$x \in S$.
\end{theorem}

\noindent These are the concrete shadows of the limit/colimit metaphor: on the line,
the conservative universal resolution is the least element and the divergent universal
resolution is the greatest.

\section{Stability}

Model a reinterpretation as a map $f : \R \to \R$; its image $f(S) = \{f(x):x\in S\}$
is again finite and nonempty.

\begin{theorem}[Stability]
Let $\varepsilon \ge 0$ and suppose $|f(x) - x| \le \varepsilon$ for every $x \in S$.
Then $\bigl| H(f(S)) - H(S) \bigr| \le 2\varepsilon$.
\end{theorem}
\begin{proof}
For every $x\in S$, $f(x) \le x+\varepsilon \le \max S + \varepsilon$, so
$\max f(S) \le \max S + \varepsilon$; and $f(\max S) \ge \max S - \varepsilon$ lies in
$f(S)$, so $\max f(S) \ge \max S - \varepsilon$. Hence
$|\max f(S) - \max S| \le \varepsilon$. Symmetrically
$|\min f(S) - \min S| \le \varepsilon$. Writing
$H(f(S)) - H(S) = (\max f(S) - \max S) - (\min f(S) - \min S)$ and applying the
triangle inequality gives the bound $2\varepsilon$.
\end{proof}

\noindent The constant $2$ is sharp: a reinterpretation may push the maximum up by
$\varepsilon$ and the minimum down by $\varepsilon$ at once, changing $H$ by
$2\varepsilon$.

\section{The spectrum of humor}

The scalar $H(S)$ organizes comedy into a spectrum. \emph{Puns} ($H(S)=0$) place the
punchline on the expected resolution: wordplay without subversion.
\emph{Narrative and observational humor} (intermediate $H(S)$) displace the punchline
from the expected resolution while keeping it connected. \emph{Absurdism} (large
$H(S)$) sends the subverting resolution far from the expected one. Monotonicity shows
the index only rises with enrichment; the diameter identity shows it is a genuine
spread; stability shows it is robust.

\section{Discussion and future directions}

Placing readings on a line yields an exact, fully attained diameter characterization
at the cost of assuming a one-dimensional interpretive axis. In richer spaces the
minimum and maximum no longer bracket the configuration and the diameter is realized
on the boundary of the convex hull; the qualitative picture is expected to persist,
with witnesses moving from endpoints to hull vertices. Natural next steps include: a
higher-dimensional diameter theorem via convex hulls, monotone under enrichment and
subadditive under overlays; a vanishing dichotomy stratifying setups by distance from
the constant locus; universal resolutions realized as colimits of directed refinement
chains; and sharper stability constants for restricted classes of reinterpretation.

\section{Conclusion}

Surprise, modelled as the gap between the most conservative and most divergent reading
of a setup, is a genuine geometric invariant: nonnegative, vanishing exactly on
constant configurations, monotone under enrichment, equal to the diameter of the
configuration, and Lipschitz-stable. The slogan that a joke is the passage from the
limit of a setup to its colimit becomes, on the line, the exact statement that
funniness is the diameter of the space of readings.

\end{document}

