"""
Demo: The Humor Spectrum -- classifying jokes by their surprise value.
Encodes each joke as a finite configuration of resolutions on a normalized
interpretive axis and classifies it as pun / observational / narrative /
absurdist according to the surprise invariant H(S) = max(S) - min(S).
"""
from __future__ import annotations
from typing import Sequence, Dict, List, Tuple


def humor(setup: Sequence[float]) -> float:
    return max(setup) - min(setup)


def classify(setup: Sequence[float]) -> str:
    h = humor(setup)
    if h == 0.0:
        return "pun (no subversion)"
    if h < 1.0:
        return "observational"
    if h < 5.0:
        return "narrative"
    return "absurdist"


def spectrum(corpus: Dict[str, Sequence[float]]) -> List[Tuple[str, float, str]]:
    rows = [(name, humor(S), classify(S)) for name, S in corpus.items()]
    return sorted(rows, key=lambda r: r[1])


if __name__ == "__main__":
    corpus = {
        "knock-knock pun": [0.0, 0.0],
        "dad joke": [0.0, 0.4],
        "observational bit": [0.0, 0.8, 1.0],
        "story with twist": [0.0, 1.2, 3.5],
        "surreal non-sequitur": [0.0, 0.1, 15.0],
    }
    for name, h, cls in spectrum(corpus):
        print(f"{name:22s}  H={h:6.2f}  -> {cls}")

