function STABILITY_CERTIFICATE(S, f, eps):
  for each x in S:
      if |f(x) - x| > eps: raise error
  h0 <- max(S) - min(S)
  img <- { f(x) : x in S }
  h1 <- max(img) - min(img)
  return |h1 - h0| <= 2*eps
